import type { ComponentProps, ReactNode } from "react";
import { Icon } from "./icon";
import { cn } from "./cn";

/** One option in a household-mode picker. `pressed` marks the active mode. */
export function ModeButton({ icon, label, description, pressed, className, ...rest }: Omit<ComponentProps<"button">, "children" | "type"> & {
  icon: string;
  /** The mode's name. */
  label: string;
  /** A short line under the label. */
  description?: ReactNode;
  pressed: boolean;
}) {
  return (
    <button type="button" data-slot="mode-button" className={cn("mode", className)} aria-pressed={pressed} {...rest}>
      <Icon n={icon} /><b>{label}</b>{description ? <small>{description}</small> : null}
    </button>
  );
}

/** Scene or routine card. `suggested` outlines it in sage. */
export function SceneCard({ icon, name, description, tag, suggested, className, ...rest }: Omit<ComponentProps<"button">, "children" | "type"> & {
  icon: string;
  /** The scene's name. */
  name: string;
  /** What it does, in a short line. */
  description?: ReactNode;
  /** A small label at the bottom: "Routine", "Suggested". */
  tag?: ReactNode;
  /** Outlines the card: Alice suggests it for now. */
  suggested?: boolean;
}) {
  return (
    <button type="button" data-slot="scene-card" data-suggested={suggested ? "" : undefined} className={cn("scene", suggested && "rec", className)} {...rest}>
      <Icon n={icon} /><b>{name}</b>{description ? <small>{description}</small> : null}{tag ? <span className="eyebrow">{tag}</span> : null}
    </button>
  );
}

/* ModeButton and SceneCard. */
.mode{display:flex;flex-direction:column;gap:6px;padding:12px;border-radius:16px;background:var(--over);text-align:left;min-height:84px;transition:transform .12s,background .2s}
.mode b{font:650 1rem var(--f-display);font-stretch:92%}
.mode small{line-height:1.25}
.mode[aria-pressed=true]{background:var(--sage);color:var(--on-sage)}
.mode[aria-pressed=true] small{color:inherit;opacity:.92}
.scene{display:flex;flex-direction:column;gap:8px;padding:14px;border-radius:18px;background:var(--tile2);text-align:left;transition:transform .12s,background .2s;min-height:112px;min-width:0;overflow-wrap:anywhere;max-width:100%}
@media(hover:hover){
  .scene:hover{background:var(--sage-soft)}
}
.scene b{font:650 1rem var(--f-display);font-stretch:92%}
.scene .ic{color:var(--sage)}
.scene.rec{outline:2px solid var(--sage);outline-offset:-2px}
@media (max-width:620px){
  .scene:last-child:nth-child(odd){grid-column:span 2}
}
